// Specific overload for a single argument (Preferred)
template <typename T>
void format(T arg) { /* Single argument handling */ }

// Specific overload for zero arguments (Base case)
void format() { /* End of recursion */ }

// Variadic Template (Generic Fallback, used for >1 argument)
template <typename T, typename... Args>
void format(T first, Args... rest) { /* Handle first, recurse on rest */ }

void check_resolution() {
    int i = 42;
    float f = 3.14f;

    // Calls format() (Base Case)
    format();

    // Calls template<T> format(T arg) (Most specific match)
    format(i);

    // Calls variadic template (T=int, Args...=float)
    format(i, f);
}
